sys_variable_value.value:
(function execute(inputs, outputs) {
    var listOfRecords = [];

    var gr = new GlideRecord(inputs.table);
    gr.addEncodedQuery(inputs.query);
    gr.query();

    while(gr.next()){
        listOfRecords.push(gr.getDisplayValue(inputs.fieldName));
    }

    outputs.listofrecords = listOfRecords;

})(inputs, outputs);

